def count_divisors(n):
    """Calculates the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

print("k | 2k | 2k^3 | d(2k^3) | Match?")
print("-" * 30)
for k in range(1, 11):
    N = 2 * (k**3)
    d_N = count_divisors(N)
    target = 2 * k
    match = "Yes" if d_N == target else "No"
    print(f"{k} | {target} | {N} | {d_N} | {match}")
